private lemma paired_physical_mellin (P : Finset ℕ) (Y : ℝ) :
    mellin (fun x : ℝ => (starRingEnd ℂ) (mobiusDivisorContinuousHead P (Y*x):ℂ)*
      (mobiusDivisorContinuousHead P x:ℂ)) (-2) = (mobiusDivisorDilationMean P Y:ℂ)

